// Controller actual P/N public lifecycle. Only the frozen P fixture index is read.
#![forbid(unsafe_code)]
use serde_json::{Value,json};
use water_contracts::v1::OpaqueId;
use water_scope_registry::v1::{Registry,RegistryError};
fn id(s:&str)->OpaqueId{OpaqueId::new(s).unwrap()}
fn main(){let i:Value=serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_SCOPE_FIXTURE_INDEX").unwrap()).unwrap()).unwrap();let mut a=Registry::new(2).unwrap();assert!(a.is_empty());let pending=a.prepare(&id("scope-bridge"),i["normal_a"].as_str().unwrap()).unwrap();assert_eq!(a.len(),1);let observation=a.preview(&pending).unwrap();let scope=a.confirm(&pending).unwrap();assert!(matches!(a.confirm(&pending),Err(RegistryError::WrongState)));let permit=a.begin_scan(&scope).unwrap();assert_eq!(a.check_permit(&permit).unwrap().identity(),observation.identity());assert!(matches!(a.begin_scan(&scope),Err(RegistryError::WrongState)));let mut b=Registry::new(2).unwrap();let other=b.prepare(&id("scope-bridge"),i["normal_a"].as_str().unwrap()).unwrap();let other=b.confirm(&other).unwrap();assert!(matches!(b.begin_scan(&scope),Err(RegistryError::InvalidCapability)));assert!(matches!(b.check_permit(&permit),Err(RegistryError::InvalidCapability)));a.cancel(&scope).unwrap();assert!(matches!(a.check_permit(&permit),Err(RegistryError::InvalidCapability)));let permit=a.begin_scan(&scope).unwrap();a.finish(&permit).unwrap();assert!(matches!(a.finish(&permit),Err(RegistryError::InvalidCapability)));let permit=a.begin_scan(&scope).unwrap();a.revoke(&scope).unwrap();assert!(a.is_empty());assert!(matches!(a.check_permit(&permit),Err(RegistryError::InvalidCapability)));let next=a.prepare(&id("scope-bridge"),i["normal_a"].as_str().unwrap()).unwrap();let next=a.confirm(&next).unwrap();assert!(matches!(a.begin_scan(&scope),Err(RegistryError::InvalidCapability)));assert!(a.begin_scan(&next).is_ok());assert!(b.begin_scan(&other).is_ok());assert!(!observation.authorization_granted()&&!observation.traversal_allowed()&&!observation.race_protection_verified());println!("{}",json!({"actual_P_N":true,"owner_binding":true,"revocation_and_replay":true,"original_N_flags_preserved":true,"native_user_gesture_verified":false,"directory_enumerated":false}));}
